#!/usr/bin/env python3
"""The overlay's text font: Roboto Condensed Medium, a subset, as a C array.

    python3 third_party/roboto_condensed/make_subset.py <RobotoCondensed[wght].ttf>

writes src/overlay/overlay_font_ui.h. The source is the variable font of that
name in google/fonts, ofl/robotocondensed, commit
69d0549e8fc7ad72e1531734c81237be401ec4fd (sha256 below). It is pinned to the
Medium weight (wght 500) and cut to:

    U+0020-007E   Basic Latin
    U+00A0-024F   Latin-1, Latin Extended-A and -B (Central European ...)
    U+0370-03FF   Greek
    U+0400-04FF   Cyrillic
    U+2010-203A   dashes, quotes, the ellipsis, per mille, angle quotes
    U+20AC U+2122 the euro and trade mark signs

Only outlines, metrics and the character map are kept: no hinting, no layout
tables, no names. Needs fontTools.
"""
import hashlib
import io
import os
import sys

from fontTools import subset
from fontTools.ttLib import TTFont
from fontTools.varLib import instancer

SHA256 = "dace262afcee68a5276f200d8026c57221735c0118ab5fda8c2c0d3dc409a8d0"
UNICODES = "U+0020-007E,U+00A0-024F,U+0370-03FF,U+0400-04FF,U+2010-203A,U+20AC,U+2122"


def main():
    data = open(sys.argv[1], "rb").read()
    digest = hashlib.sha256(data).hexdigest()
    if digest != SHA256:
        sys.exit("not the RobotoCondensed[wght].ttf of google/fonts 69d0549 (sha256 %s)" % digest)
    font = TTFont(io.BytesIO(data))
    font = instancer.instantiateVariableFont(font, {"wght": 500})
    opts = subset.Options()
    opts.hinting = False
    opts.desubroutinize = True
    opts.layout_features = []
    opts.name_IDs = []
    opts.notdef_outline = True
    opts.drop_tables += ["FFTM", "GDEF", "GPOS", "GSUB", "STAT", "MVAR", "HVAR"]
    sub = subset.Subsetter(opts)
    sub.populate(unicodes=subset.parse_unicodes(UNICODES))
    sub.subset(font)
    out = io.BytesIO()
    font.save(out)
    ttf = out.getvalue()
    here = os.path.dirname(os.path.abspath(__file__))
    dest = os.path.join(here, "..", "..", "src", "overlay", "overlay_font_ui.h")
    hhea, os2, head = font["hhea"], font["OS/2"], font["head"]
    with open(dest, "w", newline="\n") as f:
        f.write("/* Generated by third_party/roboto_condensed/make_subset.py: Roboto Condensed\n"
                " * Medium, a subset (%d characters, %d bytes). Copyright 2011 The Roboto Project\n"
                " * Authors. SIL Open Font License 1.1: third_party/roboto_condensed/OFL.txt.\n"
                " * Do not edit. */\n" % (len(font.getBestCmap()), len(ttf)))
        f.write("/* Font units: em, ascent - descent (what Dear ImGui calls the size), the\n"
                " * capitals' height. */\n")
        f.write("#define OVERLAY_FONT_UI_EM %d\n" % head.unitsPerEm)
        f.write("#define OVERLAY_FONT_UI_HEIGHT %d\n" % (hhea.ascent - hhea.descent))
        f.write("#define OVERLAY_FONT_UI_ASCENT %d\n" % hhea.ascent)
        f.write("#define OVERLAY_FONT_UI_CAPS %d\n" % os2.sCapHeight)
        f.write("static const unsigned char k_overlay_font_ui[%d] = {\n" % len(ttf))
        for i in range(0, len(ttf), 20):
            f.write("    " + ",".join(str(b) for b in ttf[i:i + 20]) + ",\n")
        f.write("};\n")
    print("%s: %d characters, %d bytes" % (os.path.normpath(dest), len(font.getBestCmap()), len(ttf)))


if __name__ == "__main__":
    main()
